from pydantic import BaseModel, Field

class HousingRecord(BaseModel):
    """A single monthly data point extracted from a housing construction report."""
    release_date: str | None = Field(
        description="The date the report was released, in YYYY-MM format, used to resolve conflicts"
    )
    data_month: str | None = Field(
        description="The month the data covers, in YYYY-MM format"
    )
    region: str | None = Field(
        description="The geographic region covered by the data"
    )
    unit_type: str | None = Field(
        description="The housing unit category (e.g., '1 unit', 'single-family')"
    )
    adjustment_type: str | None = Field(
        description="The seasonal adjustment status of the data"
    )
    value: float | None = Field(
        description="The number of units completed (as a decimal number)"
    )
    unit_scale: str | None = Field(
        description="The scale of the unit (e.g., 'thousands')"
    )
    source_doc_id: str | None = Field(
        description="An identifier for the source document (e.g., 'Document 1')"
    )

class Parse(BaseModel):
    housing_records: list[HousingRecord]
